"""
soot_analysis.py -- Jimple-like intermediate representation and core
whole-program analysis utilities (a Soot work-alike).

This is layer 1 of the analysis stack.  It converts the neutral
:mod:`program_model` representation into a Jimple-like three-address IR,
registers everything in a global ``Scene``, builds a Class Hierarchy
Analysis (CHA) call graph, and provides classic intra-procedural
optimisations (copy propagation, dead-assignment elimination,
unreachable-code elimination).

Layer 2 (``flowdroid_analysis``) and layer 3 (``stubdroid_analysis``)
build on the IR, the ``Scene`` and the ``CallGraph`` exposed here.

Vocabulary follows Soot as closely as is reasonable in Python:

    Value        -- Local, Constant, FieldRef, InvokeExpr, NewExpr, ...
    Unit / Stmt  -- AssignStmt, IdentityStmt, InvokeStmt, ReturnStmt, ...
    JimpleBody   -- locals + units of one method
    SootField / SootMethod / SootClass
    Scene        -- the global registry (``Scene.v()``)
    Hierarchy    -- sub/super class queries and virtual dispatch
    CallGraph    -- Edge set produced by ``CHATransformer``
    UnitGraph    -- intra-procedural CFG
    CopyPropagator / DeadAssignmentEliminator / UnreachableCodeEliminator

Run standalone::

    python3 soot_analysis.py
"""

from __future__ import annotations

import os
import sys
from dataclasses import dataclass, field as _dc_field
from typing import Any, Iterable, Iterator, Optional

from program_model import (
    ClassDef,
    FieldRef,
    Method,
    MethodBody,
    MethodSignature,
    Program,
    Statement,
    Type,
    Variable,
    load_all_benchmarks,
    load_program,
)
from utils import (
    Timer,
    build_class_index,
    build_hierarchy,
    build_method_index,
    get_all_subclasses,
)

BENCHMARK_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")

PRIMITIVE_TYPE_NAMES = frozenset(
    {"int", "long", "short", "byte", "char", "float", "double", "boolean", "void"}
)

OBJECT_CLASS = "java.lang.Object"


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


def make_type(name: str) -> Type:
    """Build a :class:`program_model.Type` from a type name string."""
    if name is None:
        name = OBJECT_CLASS
    is_array = name.endswith("[]")
    base = name
    while base.endswith("[]"):
        base = base[:-2]
    return Type(
        name=name,
        is_primitive=base in PRIMITIVE_TYPE_NAMES and not is_array,
        is_array=is_array,
        element_type=base if is_array else None,
    )


VOID_TYPE = make_type("void")
INT_TYPE = make_type("int")
BOOLEAN_TYPE = make_type("boolean")
OBJECT_TYPE = make_type(OBJECT_CLASS)
STRING_TYPE = make_type("java.lang.String")
NULL_TYPE = make_type("null_type")
UNKNOWN_TYPE = make_type("unknown")


def is_reference_type(t: Type | None) -> bool:
    """True for object/array types (i.e. things that can carry taint)."""
    if t is None:
        return True
    return not t.is_primitive or t.is_array


# ---------------------------------------------------------------------------
# Jimple values
# ---------------------------------------------------------------------------


class Value:
    """Base class of the Jimple value hierarchy."""

    __slots__ = ()

    def get_type(self) -> Type:  # pragma: no cover - overridden
        return UNKNOWN_TYPE

    def get_use_boxes(self) -> list["Value"]:
        """Values used by this value (transitively, excluding ``self``)."""
        return []

    def used_locals(self) -> list["Local"]:
        out: list[Local] = []
        for v in self.get_use_boxes():
            if isinstance(v, Local):
                out.append(v)
        if isinstance(self, Local):
            out.append(self)
        return out

    # -- value identity is structural, which keeps analyses deterministic --
    def _key(self) -> tuple:
        return (type(self).__name__, str(self))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Value):
            return NotImplemented
        return self._key() == other._key()

    def __hash__(self) -> int:
        return hash(self._key())

    def __repr__(self) -> str:
        return str(self)


class Local(Value):
    """A Jimple local variable (``r0``, ``i1``, ...)."""

    __slots__ = ("name", "type", "is_parameter", "param_index")

    def __init__(
        self,
        name: str,
        var_type: Type | None = None,
        is_parameter: bool = False,
        param_index: int = -1,
    ) -> None:
        self.name = name
        self.type = var_type if var_type is not None else UNKNOWN_TYPE
        self.is_parameter = is_parameter
        self.param_index = param_index

    # Soot spells it ``getName`` / ``getType``.
    def get_name(self) -> str:
        return self.name

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("Local", self.name)

    def __str__(self) -> str:
        return self.name


class Constant(Value):
    """A compile-time constant."""

    __slots__ = ("value", "type", "text")

    def __init__(self, value: Any, const_type: Type | None = None, text: str | None = None) -> None:
        self.value = value
        self.type = const_type if const_type is not None else UNKNOWN_TYPE
        self.text = text if text is not None else str(value)

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("Constant", self.text)

    def __str__(self) -> str:
        return self.text


class IntConstant(Constant):
    __slots__ = ()

    def __init__(self, value: int, text: str | None = None) -> None:
        super().__init__(int(value), INT_TYPE, text if text is not None else str(value))


class LongConstant(Constant):
    __slots__ = ()

    def __init__(self, value: int, text: str | None = None) -> None:
        super().__init__(int(value), make_type("long"), text if text is not None else str(value))


class DoubleConstant(Constant):
    __slots__ = ()

    def __init__(self, value: float, text: str | None = None) -> None:
        super().__init__(float(value), make_type("double"), text if text is not None else str(value))


class StringConstant(Constant):
    __slots__ = ()

    def __init__(self, value: str, text: str | None = None) -> None:
        super().__init__(value, STRING_TYPE, text if text is not None else '"%s"' % value)


class BooleanConstant(Constant):
    __slots__ = ()

    def __init__(self, value: bool, text: str | None = None) -> None:
        super().__init__(
            bool(value), BOOLEAN_TYPE, text if text is not None else ("true" if value else "false")
        )


class NullConstant(Constant):
    __slots__ = ()

    def __init__(self) -> None:
        super().__init__(None, NULL_TYPE, "null")


class ClassConstant(Constant):
    __slots__ = ()

    def __init__(self, class_name: str) -> None:
        super().__init__(class_name, make_type("java.lang.Class"), "class %s" % class_name)


class ThisRef(Value):
    """``@this`` -- only valid on the right of an :class:`IdentityStmt`."""

    __slots__ = ("type",)

    def __init__(self, this_type: Type | None = None) -> None:
        self.type = this_type if this_type is not None else OBJECT_TYPE

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("ThisRef", self.type.name)

    def __str__(self) -> str:
        return "@this: %s" % self.type.name


class ParameterRef(Value):
    """``@parameterN`` -- only valid on the right of an :class:`IdentityStmt`."""

    __slots__ = ("index", "type")

    def __init__(self, index: int, param_type: Type | None = None) -> None:
        self.index = index
        self.type = param_type if param_type is not None else OBJECT_TYPE

    def get_index(self) -> int:
        return self.index

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("ParameterRef", self.index)

    def __str__(self) -> str:
        return "@parameter%d: %s" % (self.index, self.type.name)


class CaughtExceptionRef(Value):
    __slots__ = ("type",)

    def __init__(self, exc_type: Type | None = None) -> None:
        self.type = exc_type if exc_type is not None else make_type("java.lang.Throwable")

    def get_type(self) -> Type:
        return self.type

    def _key(self) -> tuple:
        return ("CaughtExceptionRef", self.type.name)

    def __str__(self) -> str:
        return "@caughtexception"


class FieldSignature:
    """``<declaring.Class: type name>``."""

    __slots__ = ("declaring_class", "name", "type")

    def __init__(self, declaring_class: str, name: str, field_type: Type | None = None) -> None:
        self.declaring_class = declaring_class
        self.name = name
        self.type = field_type if field_type is not None else OBJECT_TYPE

    def full_signature(self) -> str:
        return "<%s: %s %s>" % (self.declaring_class, self.type.name, self.name)

    def get_sub_signature(self) -> str:
        return "%s %s" % (self.type.name, self.name)

    def __str__(self) -> str:
        return self.full_signature()

    def __repr__(self) -> str:
        return self.full_signature()

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, FieldSignature):
            return NotImplemented
        return self.full_signature() == other.full_signature()

    def __hash__(self) -> int:
        return hash(self.full_signature())


class SootField:
    """A field declared by a :class:`SootClass`."""

    __slots__ = ("name", "type", "declaring_class", "is_static", "is_final", "access")

    def __init__(
        self,
        name: str,
        field_type: Type,
        declaring_class: str,
        is_static: bool = False,
        is_final: bool = False,
        access: str = "public",
    ) -> None:
        self.name = name
        self.type = field_type
        self.declaring_class = declaring_class
        self.is_static = is_static
        self.is_final = is_final
        self.access = access

    def get_name(self) -> str:
        return self.name

    def get_type(self) -> Type:
        return self.type

    def get_signature(self) -> FieldSignature:
        return FieldSignature(self.declaring_class, self.name, self.type)

    def get_sub_signature(self) -> str:
        return "%s %s" % (self.type.name, self.name)

    def __str__(self) -> str:
        return self.get_signature().full_signature()

    def __repr__(self) -> str:
        return str(self)


class FieldRefValue(Value):
    """Common base of instance and static field references."""

    __slots__ = ("field",)

    def __init__(self, field_sig: FieldSignature) -> None:
        self.field = field_sig

    def get_field(self) -> FieldSignature:
        return self.field

    def get_field_name(self) -> str:
        return self.field.name

    def get_type(self) -> Type:
        return self.field.type


class InstanceFieldRef(FieldRefValue):
    """``base.field``."""

    __slots__ = ("base",)

    def __init__(self, base: Value, field_sig: FieldSignature) -> None:
        super().__init__(field_sig)
        self.base = base

    def get_base(self) -> Value:
        return self.base

    def get_use_boxes(self) -> list[Value]:
        return [self.base]

    def _key(self) -> tuple:
        return ("InstanceFieldRef", str(self.base), self.field.full_signature())

    def __str__(self) -> str:
        return "%s.%s" % (self.base, self.field.name)


class StaticFieldRef(FieldRefValue):
    """``Class.field``."""

    __slots__ = ()

    def _key(self) -> tuple:
        return ("StaticFieldRef", self.field.full_signature())

    def __str__(self) -> str:
        return "%s.%s" % (self.field.declaring_class, self.field.name)


class ArrayRef(Value):
    """``base[index]``."""

    __slots__ = ("base", "index", "type")

    def __init__(self, base: Value, index: Value, elem_type: Type | None = None) -> None:
        self.base = base
        self.index = index
        self.type = elem_type if elem_type is not None else OBJECT_TYPE

    def get_base(self) -> Value:
        return self.base

    def get_index(self) -> Value:
        return self.index

    def get_type(self) -> Type:
        return self.type

    def get_use_boxes(self) -> list[Value]:
        return [self.base, self.index]

    def _key(self) -> tuple:
        return ("ArrayRef", str(self.base), str(self.index))

    def __str__(self) -> str:
        return "%s[%s]" % (self.base, self.index)


class Expr(Value):
    """Base class of Jimple expressions."""

    __slots__ = ()


class NewExpr(Expr):
    """``new Type``."""

    __slots__ = ("base_type",)

    def __init__(self, base_type: Type) -> None:
        self.base_type = base_type

    def get_base_type(self) -> Type:
        return self.base_type

    def get_type(self) -> Type:
        return self.base_type

    def _key(self) -> tuple:
        return ("NewExpr", self.base_type.name)

    def __str__(self) -> str:
        return "new %s" % self.base_type.name


class NewArrayExpr(Expr):
    """``new Type[size]``."""

    __slots__ = ("base_type", "size")

    def __init__(self, base_type: Type, size: Value | None = None) -> None:
        self.base_type = base_type
        self.size = size if size is not None else IntConstant(0)

    def get_base_type(self) -> Type:
        return self.base_type

    def get_type(self) -> Type:
        return self.base_type

    def get_use_boxes(self) -> list[Value]:
        return [self.size]

    def _key(self) -> tuple:
        return ("NewArrayExpr", self.base_type.name, str(self.size))

    def __str__(self) -> str:
        return "newarray (%s)[%s]" % (self.base_type.name, self.size)


class CastExpr(Expr):
    """``(Type) op``."""

    __slots__ = ("op", "cast_type")

    def __init__(self, op: Value, cast_type: Type) -> None:
        self.op = op
        self.cast_type = cast_type

    def get_op(self) -> Value:
        return self.op

    def get_cast_type(self) -> Type:
        return self.cast_type

    def get_type(self) -> Type:
        return self.cast_type

    def get_use_boxes(self) -> list[Value]:
        return [self.op]

    def _key(self) -> tuple:
        return ("CastExpr", self.cast_type.name, str(self.op))

    def __str__(self) -> str:
        return "(%s) %s" % (self.cast_type.name, self.op)


class InstanceOfExpr(Expr):
    __slots__ = ("op", "check_type")

    def __init__(self, op: Value, check_type: Type) -> None:
        self.op = op
        self.check_type = check_type

    def get_type(self) -> Type:
        return BOOLEAN_TYPE

    def get_use_boxes(self) -> list[Value]:
        return [self.op]

    def _key(self) -> tuple:
        return ("InstanceOfExpr", self.check_type.name, str(self.op))

    def __str__(self) -> str:
        return "%s instanceof %s" % (self.op, self.check_type.name)


class BinopExpr(Expr):
    """``op1 <symbol> op2`` -- also used for the generic multi-operand case."""

    __slots__ = ("op1", "op2", "symbol", "type")

    def __init__(
        self, op1: Value, op2: Value, symbol: str = "+", result_type: Type | None = None
    ) -> None:
        self.op1 = op1
        self.op2 = op2
        self.symbol = symbol
        self.type = result_type if result_type is not None else UNKNOWN_TYPE

    def get_op1(self) -> Value:
        return self.op1

    def get_op2(self) -> Value:
        return self.op2

    def get_symbol(self) -> str:
        return self.symbol

    def get_type(self) -> Type:
        return self.type

    def get_use_boxes(self) -> list[Value]:
        return [self.op1, self.op2]

    def _key(self) -> tuple:
        return ("BinopExpr", str(self.op1), self.symbol, str(self.op2))

    def __str__(self) -> str:
        return "%s %s %s" % (self.op1, self.symbol, self.op2)


class ConditionExpr(BinopExpr):
    """A comparison used by :class:`IfStmt`."""

    __slots__ = ("text",)

    def __init__(
        self,
        op1: Value,
        op2: Value,
        symbol: str = "==",
        text: str | None = None,
    ) -> None:
        super().__init__(op1, op2, symbol, BOOLEAN_TYPE)
        self.text = text

    def _key(self) -> tuple:
        return ("ConditionExpr", self.text or str(super().__str__()))

    def __str__(self) -> str:
        if self.text:
            return self.text
        return "%s %s %s" % (self.op1, self.symbol, self.op2)


class PhiExpr(Expr):
    """An n-ary value merge -- used when a statement mentions several locals."""

    __slots__ = ("operands", "text", "type")

    def __init__(self, operands: list[Value], text: str = "", result_type: Type | None = None):
        self.operands = list(operands)
        self.text = text
        self.type = result_type if result_type is not None else UNKNOWN_TYPE

    def get_type(self) -> Type:
        return self.type

    def get_use_boxes(self) -> list[Value]:
        return list(self.operands)

    def _key(self) -> tuple:
        return ("PhiExpr", self.text, tuple(str(o) for o in self.operands))

    def __str__(self) -> str:
        return self.text or ("Phi(%s)" % ", ".join(str(o) for o in self.operands))


class SootMethodRef:
    """An unresolved reference to a method (Soot's ``SootMethodRef``)."""

    __slots__ = ("signature",)

    def __init__(self, signature: MethodSignature) -> None:
        self.signature = signature

    @property
    def declaring_class(self) -> str:
        return self.signature.class_name

    @property
    def name(self) -> str:
        return self.signature.method_name

    @property
    def parameter_types(self) -> list[str]:
        return list(self.signature.param_types)

    @property
    def return_type(self) -> str:
        return self.signature.return_type

    def get_signature(self) -> str:
        return self.signature.full_signature()

    def get_sub_signature(self) -> str:
        return sub_signature_of(self.signature)

    def resolve(self, scene: "Scene | None" = None) -> "SootMethod | None":
        scene = scene or Scene.v()
        return scene.get_method_unsafe(self.signature.full_signature())

    def __str__(self) -> str:
        return self.signature.full_signature()

    def __repr__(self) -> str:
        return str(self)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, SootMethodRef):
            return NotImplemented
        return self.get_signature() == other.get_signature()

    def __hash__(self) -> int:
        return hash(self.get_signature())


def sub_signature_of(signature: MethodSignature) -> str:
    """``void foo(java.lang.String)`` -- the class-independent part."""
    return "%s %s(%s)" % (
        signature.return_type,
        signature.method_name,
        ", ".join(signature.param_types),
    )


class InvokeExpr(Expr):
    """Base class of the four Jimple invoke expressions."""

    __slots__ = ("method_ref", "args")

    def __init__(self, method_ref: SootMethodRef, args: list[Value] | None = None) -> None:
        self.method_ref = method_ref
        self.args = list(args or [])

    # -- Soot-style accessors ------------------------------------------------
    def get_method_ref(self) -> SootMethodRef:
        return self.method_ref

    def get_method(self) -> SootMethodRef:  # convenience alias
        return self.method_ref

    def get_signature(self) -> str:
        return self.method_ref.get_signature()

    def get_args(self) -> list[Value]:
        return list(self.args)

    def get_arg(self, index: int) -> Value | None:
        if 0 <= index < len(self.args):
            return self.args[index]
        return None

    def get_arg_count(self) -> int:
        return len(self.args)

    def get_type(self) -> Type:
        return make_type(self.method_ref.return_type)

    def get_base(self) -> Value | None:
        return None

    def get_use_boxes(self) -> list[Value]:
        return list(self.args)

    @property
    def kind(self) -> str:  # pragma: no cover - overridden
        return "invoke"

    def _key(self) -> tuple:
        return (
            type(self).__name__,
            str(self.get_base()),
            self.method_ref.get_signature(),
            tuple(str(a) for a in self.args),
        )

    def __str__(self) -> str:
        arglist = ", ".join(str(a) for a in self.args)
        return "%s %s(%s)" % (self.kind + "invoke", self.method_ref.get_signature(), arglist)


class InstanceInvokeExpr(InvokeExpr):
    """An invoke with a receiver."""

    __slots__ = ("base",)

    def __init__(
        self, base: Value, method_ref: SootMethodRef, args: list[Value] | None = None
    ) -> None:
        super().__init__(method_ref, args)
        self.base = base

    def get_base(self) -> Value:
        return self.base

    def get_use_boxes(self) -> list[Value]:
        return [self.base] + list(self.args)

    def __str__(self) -> str:
        arglist = ", ".join(str(a) for a in self.args)
        return "%sinvoke %s.%s(%s)" % (
            self.kind,
            self.base,
            self.method_ref.get_signature(),
            arglist,
        )


class VirtualInvokeExpr(InstanceInvokeExpr):
    __slots__ = ()

    @property
    def kind(self) -> str:
        return "virtual"


class SpecialInvokeExpr(InstanceInvokeExpr):
    __slots__ = ()

    @property
    def kind(self) -> str:
        return "special"


class InterfaceInvokeExpr(InstanceInvokeExpr):
    __slots__ = ()

    @property
    def kind(self) -> str:
        return "interface"


class StaticInvokeExpr(InvokeExpr):
