# ---------------------------------------------------------------------------
# Bodies, methods, classes
# ---------------------------------------------------------------------------


class JimpleBody:
    """The Jimple body of one method: locals plus an ordered unit chain."""

    def __init__(
        self,
        method: "SootMethod | None" = None,
        locals_: list[Local] | None = None,
        units: list[Unit] | None = None,
        this_local: Local | None = None,
        param_locals: list[Local] | None = None,
    ) -> None:
        self.method = method
        self.locals: list[Local] = list(locals_ or [])
        self.units: list[Unit] = list(units or [])
        self.this_local = this_local
        self.param_locals: list[Local] = list(param_locals or [])
        self.traps: list[dict] = []

    # -- Soot-style accessors ------------------------------------------------
    def get_method(self) -> "SootMethod | None":
        return self.method

    def get_units(self) -> list[Unit]:
        return self.units

    def get_locals(self) -> list[Local]:
        return self.locals

    def get_this_local(self) -> Local | None:
        return self.this_local

    def get_parameter_local(self, index: int) -> Local | None:
        if 0 <= index < len(self.param_locals):
            return self.param_locals[index]
        return None

    def get_parameter_locals(self) -> list[Local]:
        return list(self.param_locals)

    def get_local_by_name(self, name: str) -> Local | None:
        for loc in self.locals:
            if loc.name == name:
                return loc
        return None

    def get_unit_by_stmt_id(self, stmt_id: int) -> Unit | None:
        for u in self.units:
            if u.stmt_id == stmt_id:
                return u
        return None

    def get_head(self) -> Unit | None:
        return self.units[0] if self.units else None

    def get_tails(self) -> list[Unit]:
        return [u for u in self.units if not u.falls_through() and not u.branches()]

    def get_return_units(self) -> list[Unit]:
        return [u for u in self.units if u.is_return()]

    def index_of(self, unit: Unit) -> int:
        for i, u in enumerate(self.units):
            if u is unit or u == unit:
                return i
        return -1

    def get_successor_of(self, unit: Unit) -> Unit | None:
        i = self.index_of(unit)
        if i >= 0 and i + 1 < len(self.units):
            return self.units[i + 1]
        return None

    def __len__(self) -> int:
        return len(self.units)

    def __iter__(self) -> Iterator[Unit]:
        return iter(self.units)

    def to_string(self) -> str:
        lines = []
        sig = self.method.get_signature() if self.method else "<unknown>"
        lines.append("%s {" % sig)
        for loc in self.locals:
            lines.append("    %s %s;" % (loc.type.name, loc.name))
        if self.locals:
            lines.append("")
        for u in self.units:
            lines.append("    stmt%-3d %s;" % (u.stmt_id, u))
        lines.append("}")
        return "\n".join(lines)

    def __str__(self) -> str:
        return self.to_string()

    def clone(self) -> "JimpleBody":
        """Deep-ish clone: fresh units, shared method reference."""
        if self.method is None:
            return JimpleBody()
        builder = IRBuilder(Scene.v())
        return builder.rebuild_body(self)


class SootMethod:
    """A method owned by a :class:`SootClass`."""

    def __init__(
        self,
        signature: MethodSignature,
        declaring_class: str,
        is_static: bool = False,
        is_abstract: bool = False,
        is_constructor: bool = False,
        is_entry_point: bool = False,
        access: str = "public",
        is_phantom: bool = False,
        is_library: bool = False,
    ) -> None:
        self.signature = signature
        self.declaring_class = declaring_class
        self.is_static = is_static
        self.is_abstract = is_abstract
        self.is_constructor = is_constructor
        self.is_entry_point = is_entry_point
        self.access = access
        self.is_phantom = is_phantom
        self.is_library = is_library
        self.active_body: JimpleBody | None = None
        self.source_method: Method | None = None

    # -- naming --------------------------------------------------------------
    @property
    def name(self) -> str:
        return self.signature.method_name

    def get_name(self) -> str:
        return self.signature.method_name

    def get_signature(self) -> str:
        return self.signature.full_signature()

    def get_sub_signature(self) -> str:
        return sub_signature_of(self.signature)

    def get_declaring_class(self) -> str:
        return self.declaring_class

    def get_declaring_soot_class(self) -> "SootClass | None":
        return Scene.v().get_soot_class_unsafe(self.declaring_class)

    def get_parameter_types(self) -> list[str]:
        return list(self.signature.param_types)

    def get_parameter_count(self) -> int:
        return len(self.signature.param_types)

    def get_return_type(self) -> Type:
        return make_type(self.signature.return_type)

    def make_ref(self) -> SootMethodRef:
        return SootMethodRef(self.signature)

    # -- body ----------------------------------------------------------------
    def has_active_body(self) -> bool:
        return self.active_body is not None

    def get_active_body(self) -> JimpleBody | None:
        return self.active_body

    def set_active_body(self, body: JimpleBody | None) -> None:
        self.active_body = body
        if body is not None:
            body.method = self
            for u in body.units:
                u.owner = self

    def retrieve_active_body(self) -> JimpleBody | None:
        return self.active_body

    def is_concrete(self) -> bool:
        return (not self.is_abstract) and self.active_body is not None

    def get_units(self) -> list[Unit]:
        return self.active_body.units if self.active_body else []

    def is_java_library_method(self) -> bool:
        return self.is_library

    def __str__(self) -> str:
        return self.get_signature()

    def __repr__(self) -> str:
        return self.get_signature()

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, SootMethod):
            return NotImplemented
        return self.get_signature() == other.get_signature()

    def __hash__(self) -> int:
        return hash(self.get_signature())


class SootClass:
    """A class or interface registered in the :class:`Scene`."""

    def __init__(
        self,
        name: str,
        super_class_name: str | None = OBJECT_CLASS,
        interfaces: list[str] | None = None,
        is_interface: bool = False,
        is_abstract: bool = False,
        is_library: bool = False,
        is_phantom: bool = False,
        is_android_component: bool = False,
        component_type: str | None = None,
    ) -> None:
        self.name = name
        if name == OBJECT_CLASS:
            super_class_name = None
        self.super_class_name = super_class_name
        self.interfaces: list[str] = list(interfaces or [])
        self.is_interface = is_interface
        self.is_abstract = is_abstract
        self.is_library = is_library
        self.is_phantom = is_phantom
        self.is_android_component = is_android_component
        self.component_type = component_type
        self.fields: dict[str, SootField] = {}
        self.methods: dict[str, SootMethod] = {}
        self.source_class: ClassDef | None = None

    # -- naming --------------------------------------------------------------
    def get_name(self) -> str:
        return self.name

    def get_short_name(self) -> str:
        return self.name.rsplit(".", 1)[-1]

    def get_package_name(self) -> str:
        return self.name.rsplit(".", 1)[0] if "." in self.name else ""

    def get_type(self) -> Type:
        return make_type(self.name)

    # -- hierarchy -----------------------------------------------------------
    def has_super_class(self) -> bool:
        return self.super_class_name is not None

    def get_super_class(self) -> "SootClass | None":
        if self.super_class_name is None:
            return None
        return Scene.v().get_soot_class_unsafe(self.super_class_name)

    def get_interfaces(self) -> list[str]:
        return list(self.interfaces)

    def is_application_class(self) -> bool:
        return not self.is_library and not self.is_phantom

    # -- members -------------------------------------------------------------
    def add_field(self, f: SootField) -> None:
        self.fields[f.name] = f

    def get_fields(self) -> list[SootField]:
        return list(self.fields.values())

    def get_field_by_name(self, name: str) -> SootField | None:
        return self.fields.get(name)

    def declares_field(self, name: str) -> bool:
        return name in self.fields

