        return None

    def get_methods_by_name(self, name: str) -> list[SootMethod]:
        return [m for m in self.methods.values() if m.name == name]

    def declares_method(self, sub_sig: str) -> bool:
        return sub_sig in self.methods

    def get_method_count(self) -> int:
